package com.wizzadrds.theworldremembers.chronicle;
import net.fabricmc.fabric.api.networking.v1.*; import net.minecraft.server.level.ServerPlayer; import java.util.*;
public final class ChronicleNetworking{private ChronicleNetworking(){} public static void init(){PayloadTypeRegistry.serverboundPlay().register(ChronicleRequestPacket.TYPE,ChronicleRequestPacket.CODEC);PayloadTypeRegistry.clientboundPlay().register(ChronicleResponsePacket.TYPE,ChronicleResponsePacket.CODEC);ServerPlayNetworking.registerGlobalReceiver(ChronicleRequestPacket.TYPE,(payload,ctx)->{ServerPlayer p=ctx.player();var b=ChronicleManager.build(p);var lines=new ArrayList<String>();lines.add("TIMELINE");b.timeline().forEach(e->lines.add(e.tick()+" | "+e.category()+" | "+e.title()+" | "+e.detail()));lines.add("PEOPLE");lines.addAll(b.people());lines.add("RELATIONSHIPS");lines.addAll(b.relationships());lines.add("FAMILIES");lines.addAll(b.families());lines.add("VILLAGES");lines.addAll(b.villages());ctx.responseSender().sendPacket(new ChronicleResponsePacket(lines));});} public static void request(){ClientPlayNetworking.send(new ChronicleRequestPacket());}}
